import{_ as t,o as n,c as e,a3 as a}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control","description":"","frontmatter":{"title":"RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control","arxiv":"2307.15818","date":"2023-07-28","authors":"Anthony Brohan, Noah Brown, Justice Carbajal, Yevgen Chebotar, Xi Chen, Krzysztof Choromanski, Tianli Ding, Danny Driess, Avinava Dubey, et al.","categories":"cs.RO, cs.CL, cs.CV, cs.LG","topics":"视觉语言动作模型, 网络知识迁移, 机器人操作","outline":[2,2]},"headers":[],"relativePath":"papers/2307.15818.md","filePath":"papers/2307.15818.md","lastUpdated":null}'),r={name:"papers/2307.15818.md"};function s(i,o,u,l,g,p){return n(),e("div",null,[...o[0]||(o[0]=[a('<h1 id="rt-2-vision-language-action-models-transfer-web-knowledge-to-robotic-control" tabindex="-1">RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control <a class="header-anchor" href="#rt-2-vision-language-action-models-transfer-web-knowledge-to-robotic-control" aria-label="Permalink to &quot;RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2307.15818" target="_blank" rel="noreferrer">2307.15818</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-07-28</td></tr><tr><td><strong>作者</strong></td><td>Anthony Brohan, Noah Brown, Justice Carbajal, Yevgen Chebotar, Xi Chen, Krzysztof Choromanski, Tianli Ding, Danny Driess, Avinava Dubey, et al.（共 54 位，Google DeepMind）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CL, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>把末端位姿增量均匀离散成 256 个 bin 并直接映射到 VLM 已有的文本 token 上，于是控制策略就是&quot;回答一个 VQA 问题&quot;，再与原始网络图文数据 co-fine-tune，让互联网语义知识不经任何新增参数就流进闭环底层控制。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文开门见山地摆出一个数量级差距：最强的语言与视觉语言模型训在数十亿级的网页 token 与图像上，而机器人交互数据即便暴力采集也难以在可见的将来匹配这个规模。反过来直接把 VLM 拿来控制机器人也不行——VLM 推理的是语义、标签与文本提示，机器人需要的是接地的底层动作，比如笛卡尔空间的末端指令。</p><p>此前把 LLM/VLM 引入机器人的做法几乎都停在&quot;高层&quot;：模型扮演一个状态机，把指令解析成 pick、place 这类原语，再交给一套独立的低层控制器执行。这套架构的代价被论文说得很清楚——<strong>低层控制器在训练时完全没有享受到互联网规模模型里的语义知识</strong>。于是本文的问题很尖锐：大规模预训练的 VLM 能不能被<strong>直接</strong>装进底层控制回路，同时提升泛化与语义推理？</p><p>这件事重要在于它决定了机器人学习的杠杆在哪。如果答案是能，那么机器人领域就自动搭上了视觉语言模型的进步曲线；如果答案是不能，机器人就只能靠自己那点数据慢慢爬。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>SayCan / PaLM-E / ChatGPT-for-Robotics</strong> 这一路把 LLM 与 VLM 用于高层规划或成功检测，属于上一节说的&quot;状态机&quot;范式，低层策略与语义知识是隔离的。</p><p><strong>CLIPort 与 MOO</strong> 是把预训练 VLM 真正接进端到端视觉运动策略的两个代表，但它们都往策略里塞进了大量结构：CLIPort 依赖受限的 2D 动作空间与标定相机；MOO 用 VLM 在图像上额外画一个彩色像素来标出目标物体，再把这张改过的图喂给 RT-1 骨干——也就是说 VLM 只是增强了感知，它的表征并没有参与策略学习。论文强调自己的关键区别是：用会<strong>生成语言</strong>的 VLM，且统一的输出空间让模型权重在语言任务与动作任务之间完全共享，不引入任何仅供动作使用的层。</p><p><strong>Gato</strong> 一类从零设计新的视觉语言动作架构，代价是放弃了已经沉没在现成 VLM 里的巨额算力投入。</p><p><strong>R3M / VC-1</strong> 代表另一条路线：预训练视觉表征。它们的问题在实验里暴露得很直接——泛化平均分只有 12 和 10，远低于连预训练都没有的 RT-1（32）。这说明纯视觉表征预训练拿不到语言侧的语义结构。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是把问题转成一个格式问题。VLM 的输出是 token 序列；机器人需要的是连续动作向量。若能把动作写成 token，两者就是同一件事，不需要新架构、不需要新参数。RT-1 已经证明把末端位姿增量离散化成 bin 是可行的，那么剩下的只是：<strong>这 256 个 bin 该借用词表里的哪些 token</strong>。</p><p>第二步是发现这个借用有两种自然写法，取决于 VLM 的分词器。PaLI-X 的分词器给 1000 以内的整数各分配了唯一 token，那就直接把 bin 序号映射到对应整数 token；PaLM-E 没有这种便利，那就覆写 256 个使用频率最低的 token——作者指出这本质上是 symbol tuning。</p><p>第三步来自一个可预料的失败：如果只用机器人数据微调，模型会忘掉预训练学到的概念，而那些概念正是全部价值所在。于是必须 co-fine-tune——把原始网页数据留在微调批次里，只调高机器人数据的采样权重（PaLI-X 约 50%，PaLM-E 约 66%）。</p><p>第四步是部署。55B 的模型不可能跑在机器人本体的 GPU 上，那就把它放到多 TPU 云服务上、通过网络查询，顺带还能一个服务喂多台机器人。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不要为机器人发明新的输出空间，直接借用语言模型已有的那个。把动作写成词表里已存在的 token，控制问题就退化成&quot;回答一个视觉问答&quot;，于是权重、预训练、乃至 chain-of-thought 这些语言侧的一切都免费继承过来。唯一必须守住的是训练时别把网页数据丢掉——一旦只用机器人数据微调，被继承的知识就会被遗忘，而那正是唯一值得继承的东西。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以指令&quot;move coke can near the person with glasses&quot;为例：</p><ol><li><strong>动作编码</strong>。动作空间是末端 6-DoF 的位置与旋转增量、夹爪张开度，外加一个离散的 episode 终止指令（策略应主动触发它以示成功）。除终止位外的连续维度各均匀离散成 256 个 bin，于是一个动作就是 8 个整数，拼成空格分隔的字符串 &quot;terminate Δpos_x Δpos_y Δpos_z Δrot_x Δrot_y Δrot_z gripper_extension&quot;，实例如 &quot;1 128 91 241 5 101 127&quot;。</li><li><strong>输入格式</strong>。机器人相机图像 + 文本任务描述，写成标准 VQA 形式：&quot;Q: what action should the robot take to [task instruction]? A:&quot;。</li><li><strong>主干</strong>。RT-2-PaLI-X 用 ViT-22B 处理图像，投影后送进一个 32B、50 层的 encoder-decoder（UL2 式）；RT-2-PaLM-E-12B 是 decoder-only LLM，用 ViT-4B 把图像投到语言 embedding 空间。Language-Table 上的 RT-2-PaLI-3B 用 ViT-G/14（2B）+ UL2-3B。</li><li><strong>Co-fine-tuning</strong>。网页侧数据主体是 WebLI（约 100 亿图文对、109 种语言，按跨模态相似度取前 10% 得到 10 亿训练样本），另有若干 captioning 与 VQA 数据集；机器人侧是 RT-1 的数据——13 台机器人在办公室厨房环境采集 17 个月，每条轨迹标注一条自然语言指令，覆盖 pick / move near / place upright / knock over / open drawer / close drawer / place into / pick from receptacle 七类技能。训练目标就是 next-token prediction，等价于机器人侧的 behavior cloning 损失。超参：PaLI-X-55B 用 lr 1e-3、batch 2048、80K 步；PaLI-X-5B 同 lr/batch、270K 步；PaLM-E-12B 用 lr 4e-4、batch 512、1M 步。</li><li><strong>输出约束</strong>。真机执行要求输出必须是合法动作 token，因此在机器人任务提示下只从合法动作 token 里采样；在标准视觉语言任务上模型仍可输出完整自然语言词表。</li><li><strong>部署</strong>。多 TPU 云服务 + 网络查询。55B 版本 1–3 Hz，5B 版本约 5 Hz。作者称这是有史以来用于直接闭环机器人控制的最大模型，比此前大一个数量级以上。</li><li><strong>Chain-of-thought 变体</strong>。在 RT-2-PaLM-E 上再微调几百步，数据里插入一个 &quot;Plan&quot; 字段用自然语言先说明这一步动作的目的，再接动作 token，例如 &quot;Instruction: I&#39;m hungry. Plan: pick rxbar chocolate. Action: 1 128 124 136 121 158 111 255.&quot;。这层增强充当 VQA（视觉推理）与操作数据（生成动作）之间的桥。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测规模</strong>：约 6,000 条真机评测轨迹，7-DoF 移动操作臂。seen tasks 沿用 RT-1 的 200+ 条指令（36 条 pick、35 条 knock、35 条 place upright、48 条 move、18 条抽屉开关、36 条从抽屉取放）；泛化评测另有 280+ 条任务，按不可见<strong>物体 / 背景 / 环境</strong>三轴各分 easy / hard。baseline 全部使用完全相同的机器人数据：RT-1（35M）、VC-1（ViT-L，解冻，语言用 Universal Sentence Encoder 编码后与图像 token 拼接过 TokenLearner 再接 RT-1 decoder）、R3M（ResNet50，同样流程）、MOO。</p><p><strong>问题一：泛化如何？</strong> 表 6 的六项泛化（物体 easy/hard、背景 easy/hard、环境 easy/hard）平均分：RT-2-PaLI-X-55B 62、RT-2-PaLM-E-12B 62、MOO 35、RT-1 32、R3M 12、VC-1 10。即约为 RT-1 与 MOO 的 2 倍、R3M 与 VC-1 的约 6 倍。而在 seen tasks 上三者接近：RT-1 92、PaLI-X-55B 91、PaLM-E-12B 93。这个对比很关键——<strong>优势完全在分布外，分布内没有提升</strong>。两个 RT-2 变体的分工也有意思：PaLM-E 版在更难的泛化场景上更好（背景 hard 71 vs 48、物体 hard 76 vs 62），PaLI-X 版在较易场景上更好（背景 easy 96 vs 75），平均打平。</p><p><strong>问题二：涌现能力能否量化？</strong> 用 A/B 测试框架（四个模型在完全相同条件下依次评测）比较 RT-2 两个变体与 RT-1、VC-1，分三类：symbol understanding（&quot;move coke can near 3&quot;、&quot;push coke can on top of heart&quot;）、reasoning（数学 &quot;move banana near the sum of two plus one&quot;、logo &quot;move cup to a search engine&quot;、营养 &quot;pick a healthy drink&quot;、颜色与多语言 &quot;mueve la manzana al vaso verde&quot;）、human recognition（名人与 CelebA 属性）。每条指令跑 5 次。总平均：RT-2-PaLI-X-55B 60、RT-2-PaLM-E-12B 40、RT-1 17、VC-1 11。分项上 PaLI-X 在 symbol 上碾压（82 vs RT-1 的 16），但<strong>在 Math 一项上只有 25，低于 PaLM-E 的 35</strong>；作者归因于 PaLM-E 的预训练配方数学更强，而 PaLI-X 偏视觉。</p><p><strong>问题三：规模与训练方式的消融。</strong> 用 PaLI-X（因为 PaLM-E 受限于可用的 PaLM/ViT 尺寸组合）比较 5B/55B 与三种训练方式，泛化平均分：5B from scratch 9、5B fine-tuning 42、5B co-fine-tuning 44、55B fine-tuning 52、55B co-fine-tuning 63。三个结论：从零训练即便 5B 也极差（差到作者直接放弃评测 55B 的从零版本）；co-fine-tuning 在两个尺寸上都优于纯微调；模型越大泛化越好。</p><p><strong>问题四：换个机器人还成立吗？</strong> 开源 Language-Table 仿真环境，把动作编码成 &quot;X Y&quot;（各取 -10 到 +10 的整数）表示末端 2D 增量设定点，co-fine-tune 一个 PaLI-3B（因而推理速率与 baseline 相当，约 5 Hz），并同时训练若干辅助预测任务（给两帧与指令预测动作、给帧预测指令、预测机械臂位置、预测两帧之间的时间步数、预测任务是否成功）。结果 90 ± 10，高于 LAVA 77 ± 4、RT-1 74 ± 13、BC-Zero 72 ± 3。</p><p><strong>问题五：chain-of-thought。</strong> 只有定性结果，没有量化：加了 Plan 字段后模型能应对更复杂的指令（找一块石头当临时锤子、给累的人挑功能饮料）。</p><p><strong>论文自陈的失败面</strong>（附录 G）：Language-Table 上模型能正确理解指令并移到正确物体，但控制不了没见过的物体动力学——笔直接滚下桌子，香蕉的质心离接触点太远。真机上明确做不好的有四类：按特定部位（如把手）抓取、机器人数据里没有的新动作（用毛巾擦拭、使用工具）、需要灵巧或高精度的动作（叠毛巾）、需要多层间接推理的长链推理。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：RT-2 把机器人动作离散成 256 个 bin 并直接借用 VLM 词表里已有的 token，于是控制变成一次 VQA 回答，不新增任何参数就能复用整个预训练主干。关键训练细节是 co-fine-tune 而非纯微调——保留网页数据能防止预训练概念被遗忘，消融里 55B 从 52 提到 63。收益完全体现在分布外：seen tasks 上与 RT-1 打平（91/93 vs 92），六项泛化平均是 RT-1 的约 2 倍、纯视觉预训练表征的约 6 倍。涌现能力（符号理解、颜色/多语言/营养推理、人物识别）在 6,000 次 A/B 评测中比 RT-1 高 2–3 倍，且完全没有额外的机器人演示。但物理技能仍被机器人数据的分布锁死——模型学会的是把已有技能用在新地方，而不是新动作。</p><p><strong>3 句话版</strong>：动作即语言 token，控制即 VQA，于是 VLM 的预训练可以零结构改动地流进底层控制。co-fine-tuning 是让这条通路不被遗忘冲垮的必要条件。语义泛化提升显著，运动能力提升为零。</p><p><strong>1 句话版</strong>：把动作塞进词表，机器人就能搭上视觉语言模型的进步曲线——但只在&quot;做什么&quot;这一维上。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>&quot;知道该对哪个物体做什么&quot;与&quot;知道怎么做&quot;是可分离的两件事，因此只补前者就能提升机器人的实用能力</strong>。整套方法建立在这个分离上——动作空间被冻结成机器人数据里那套 pick/move-near 的 256-bin 离散化，网络知识只被允许改变&quot;选哪个目标、去哪个位置&quot;。</p><p>论文自己给出的反证相当直接。附录 G 里，模型在 Language-Table 上<strong>正确理解了指令并移动到了正确的物体</strong>，然后笔滚下桌子、香蕉被从质心之外的位置推动——语义环节全对，物理环节全错。真机侧列出的四类失败也全部落在运动一侧。而作者在 Limitations 里承认&quot;机器人不会因为这些额外经验而获得任何新动作&quot;，把原因归给&quot;数据在技能轴上不够多样&quot;。</p><p>问题在于，这个归因把一个可能的结构性限制说成了数据量问题。如果 256-bin 的末端增量表示本身无法编码&quot;擦拭&quot;这种带接触力与周期性的技能，那么再多样的技能数据也救不了；反过来若真是数据问题，就应该能给出&quot;技能多样性增加 → 新动作出现&quot;的趋势证据，而论文没有。更值得警惕的是评测设计的自证性：全部涌现能力评测的<strong>运动</strong>都是 pick 或 move-near，即分布内；这套评测在设计上就不可能暴露运动侧的失败。所以&quot;web knowledge transfers to robotic control&quot;这句话，被实验真正支持的强度只到&quot;transfers to robotic task selection&quot;。以上属于基于证据的推断，不是作者的声明。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要真机，一周可完成，目标是审计动作 token 与语言 token 共用词表的代价。取一个开源 VLM（如 PaliGemma 或同量级模型），在一份开源机器人数据（Language-Table 或 Open X-Embodiment 的一个子集）上做 LoRA co-fine-tuning，构造两个变体：<strong>A</strong> 照 PaLI-X 的做法把 256 个 bin 映射到已有的整数 token；<strong>B</strong> 照 PaLM-E 的做法覆写 256 个最低频 token。两者训练数据、步数、学习率完全一致。</p><p>测三件事：动作预测精度（held-out 轨迹上的 bin 级准确率）、通用 VQA 能力（微调前后在 VQAv2 或同类集上的分差）、以及一个专门的数值推理小集（GSM8K 子集或简单算术 VQA）的分差。判据很干脆：若 A 与 B 的动作精度接近，而 A 在数值推理上的退化显著大于 B，就说明&quot;复用整数 token&quot;确实会污染模型的数字语义——这正好为 §11 的替代解释提供证据。若两者退化相当，则 RT-2 论文对 Math 结果的归因（预训练配方差异）更可信。附带做一个便宜的诊断：在 A 变体上比较微调前后整数 token embedding 的余弦漂移，与随机同频 token 的漂移做对照。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者可以给出的替代解释针对论文最有意思的一个数字：RT-2-PaLI-X-55B 在几乎所有维度上都碾压 RT-2-PaLM-E-12B（symbol 82 vs 36、总平均 60 vs 40），<strong>唯独在 Math 上落后（25 vs 35）</strong>。论文把这归因于 PaLM-E 的预训练混合更擅长数学计算。但存在一个同样与数据相容、且代价更大的解释：PaLI-X 把动作 bin 直接映射到整数 token，训练时这些整数 token 被反复用作&quot;关节位移量&quot;而非&quot;数量&quot;，语义被覆盖；PaLM-E 覆写的是最低频 token，不碰数字。也就是说，<strong>Math 上的落后可能是动作 tokenization 的直接副作用，而不是预训练配方的差异</strong>。</p><p>如果这个解释成立，它推翻的是本文最核心的卖点之一——&quot;不引入任何仅供动作使用的参数、权重完全共享&quot;被呈现为纯粹的优点，而实际上共享是有代价的，且代价恰好落在被同时用作动作编码的那部分语义上。</p><p>具体攻击实验：在同一个 PaLI-X 基座上训练两个 RT-2 变体，唯一区别是动作 bin 的 token 选择（整数 token vs 新增/最低频 token），其余数据、步数、超参全同。然后同时跑三项：机器人泛化评测、Math 类涌现评测、以及纯语言的数值推理基准。若&quot;整数 token&quot;版本在机器人指标上打平而在数值推理上明显更差，论文对 Math 差距的归因就必须改写，且&quot;完全共享权重&quot;这一设计需要附上一条明确的注意事项。论文防守这一攻击的现有证据只有一句归因陈述，没有对照实验。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：RT-2 把动作变成了语言，但它变的是<strong>这一台机器人的这一套末端增量</strong>——256 个 bin 是从特定机器人的运动统计里切出来的，与&quot;擦拭&quot;&quot;拧&quot;&quot;敲&quot;这些人类会用的动作词之间没有任何对应。结果就是 §9 那个断裂：名词与关系可以从网上迁移过来，动词不能。论文把这归为数据多样性问题并提议采集人类视频，但采集更多数据并不改变&quot;动作词表由机器人数据定义&quot;这一结构。</p><p><strong>新 framing</strong>：把<strong>动作词表本身</strong>当作一个应该从网络数据里学出来的东西，而不是从机器人数据里切出来的东西。也就是说，先在无标注人类视频上学一套离散的潜在动作码本，让&quot;擦拭&quot;在码本里就是一个（或几个）稳定的码字；再把机器人轨迹映射进同一个码本。这样 VLM 在预训练阶段接触过的&quot;wipe&quot;这个词，与执行时要发出的码字之间就有了共享的语义基底，动词才有可能像名词一样迁移。这不是&quot;再加一个模块&quot;，而是把 tokenizer 从机器人一侧搬到了网络一侧。</p><p>可借鉴的相邻领域工具很成熟：语音领域从无标注音频里学离散声学单元（HuBERT / VQ-wav2vec 那条线）已经证明&quot;自监督学出来的离散单元可以当作跨说话人的共享词表&quot;；而视频侧的逆动力学模型（从相邻两帧反推中间发生了什么）提供了不需要动作标签的监督信号。</p><p><strong>第一个实验</strong>：先验证码本的跨具身可迁移性，不碰策略训练。用逆动力学目标在人类第一人称视频（Ego4D 一类）上学一个小码本（例如 512 个码字），然后把机器人演示轨迹的相邻帧也编码进去，测两件事：机器人轨迹的码字分布是否覆盖码本的一个连贯子集（而非退化成少数几个码字），以及同一技能标签（pick / wipe / pour）下人类片段与机器人片段的码字分布 KL 散度是否显著小于跨技能的。若跨具身对齐成立，下一步才是把码字当作 RT-2 的动作 token，并检验&quot;机器人数据里从未出现过的技能词&quot;能否被零样本触发——那将是对 §9 那条断裂的直接检验。</p>',52)])])}const d=t(r,[["render",s]]);export{c as __pageData,d as default};
